-- RootishArrayStack：时间与空间复杂度汇总，并完成模块路径。
INSERT INTO knowledge_point (name, description, course_id, parent_id, content_key, content_source, content_version, content_review_status, sort_order, deleted)
SELECT 'RootishArrayStack 的时间与空间复杂度', 'get/set 为 O(1)，按位更新为 O(1+n-i)，块增缩总成本为 O(m)，额外空间为 O(sqrt(n))。', course.id, parent.id, 'ods-rootisharraystack-performance', 'AISTU', 1, 'REVIEWED', 34, 0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-stacks-queues-arrays' LEFT JOIN knowledge_point existing ON existing.content_key='ods-rootisharraystack-performance' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id, content_key, content_version, review_status, title, lesson_json, check_json)
SELECT point.id,'ods-rootisharraystack-performance',1,'REVIEWED','RootishArrayStack 的时间与空间复杂度',JSON_OBJECT('summary','RootishArrayStack 的 get/set 为 O(1)；忽略 grow/shrink 时，add(i,x) 为 O(1+n-i)、remove(i) 为 O(n-i)。从空结构开始的 m 次更新中块增缩总成本为 O(m)，额外空间为 O(sqrt(n))。','steps',JSON_ARRAY('下标公式支持 O(1) 随机访问','中间更新仍需搬移后继元素','块增缩不复制旧元素且其成本可线性摊还','递增块布局将额外空间限制为 O(sqrt(n))'),'prerequisite',JSON_OBJECT('contentKey','ods-rootisharraystack-space','title','RootishArrayStack 的浪费空间界','description','先掌握块布局的空间收益。')),JSON_OBJECT('id','rootisharraystack-performance-v1','prompt','RootishArrayStack 相对于单一 ArrayStack 的核心空间权衡是什么？','options',JSON_ARRAY(JSON_OBJECT('id','SQRT_SPACE','text','保持 O(1) 随机访问，同时将额外空间界降为 O(sqrt(n))'),JSON_OBJECT('id','CONSTANT_SPACE','text','始终只需要 O(1) 个额外槽位')),'correctOptionId','SQRT_SPACE','correctExplanation','正确：递增块和收缩规则使空槽与块目录的量级为 O(sqrt(n))。','incorrectExplanation','不正确：末尾块空槽和块目录都随 n 增长，不能保证常数额外空间。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='ods-rootisharraystack-performance' AND existing.content_version=1 WHERE point.content_key='ods-rootisharraystack-performance' AND existing.id IS NULL;
